Ext.define('BNK.view.Budget.bgx.com.BgxItmCpnt02MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxItmCpnt02MViewController',

    config: {
        viewId: 'BgxItmCpnt02M'
    },

    /* BgxItmCpnt32M */
    setExpItemInputData: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            cmm = refs.common_input_container,
            cmmRefs = cmm.getReferences();

        vm.set('expItemInputData', vm.get('expItemData'));

        // codeList (계정과목)
        if (vm.get('codeList')) {
            cmmRefs.xpnitKeyCd.getStore().add(vm.get('codeList.xpnitCodeList'));
        }
        cmmRefs.imgPanel.setHidden(true);	// 사진

        if (vm.get('readOnlyFlag')) {
            // 상세조회화면
            if (vm.get('expItemData').xpnitKeyCd == Constants.xpnitKeyCd.SUPPLIES_EXPENSE) {
                // 소모품비 - 영수증
                refs.cardEvidImag.setHidden(false);
            }

            if(Ext.isEmpty(vm.get('expItemData.expItemUserInfo'))){
                cmmRefs.btnXpnitInfo.setDisabled(true); //직접 추가인 경우, 집행대상 조회 불가하도록 설정
            }

            me.fnSetSummaryUserLabel();		// 집행대상라벨

            // 지급정보
            var dgDsbInfo = vm.get('applyInfo.dgDsbInfo');
            if (dgDsbInfo) {
                var bcncSeq = dgDsbInfo.bcncSeq,		// 사번
                    bcncDpwnm = dgDsbInfo.bcncDpwnm;	// 이름
                cmmRefs.dgDsbInfoGrid.setHidden(true);
                cmmRefs.dgDsbInfoCont.setHidden(false);
                cmmRefs.dgDsbInfoLabel.setHtml(bcncSeq + ' / ' + bcncDpwnm);
            }
        } else {
            // 신청서 작성
            vm.set('applyInfo.dgDsbInfo.bcncSeq', SecurityUtils.getPrincipal().hrHrpmEmpId);	//지급정보 초기값 (본인)
        }

        if(Property.PROFILE == 'L' && !vm.get('readOnlyFlag')) {
            cmmRefs.webOnly.setHidden(false);
        }
    },

    /* 집행대상라벨 */
    fnSetSummaryUserLabel: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            expItemData = Ext.clone(vm.get('expItemData')),
            userRecords = expItemData.expItemUserInfo,
            trnsAmt = expItemData.trnsAmt,  //공급가액
            innerEmpeCnt = 0,
            outerEmpeCnt = 0,
            rtnStr = '',
            defaultStr = '승인금액',
            xpnitKeyCd = expItemData.xpnitKeyCd,
            xpnitKeyNm = expItemData.xpnitKeyNm;

        if (userRecords) {
            for (var i = 0; i < userRecords.length; i++) {
                var record = userRecords[i];
                if (record.stfDvcd == Constants.stfDvcd.IN) {
                    innerEmpeCnt++;
                } else {
                    outerEmpeCnt++;
                }
            }
            var amtByUser = (innerEmpeCnt == 0 ? 0 : Math.round(trnsAmt / innerEmpeCnt));

            rtnStr = Ext.String.format('<span style = "line-height : 20px;">집행대상 ( 총 <span style ="color : red;">{0}</span>명 ) <br>'
                                       + '[ 내부직원 {1} 명 / 외부직원 {2} 명 ] <br>'
                                       + '<span style = "color :gray;" >[{3} 기준 1인당 {4}원]</span></span>',
                                       userRecords.length, innerEmpeCnt, outerEmpeCnt, defaultStr ,
                                       amtByUser.toString().replace(/\B(?=(\d{3})+(?!\d))/g,","));

        }
        vm.set('expItemData.summaryUserLabel', rtnStr);
    },

    /* 영수증 팝업 */
    openEvidImgFilePopUp: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();

        Ext.create('BgxItmCpnt52M', {
            param : vm.get('expItemData.evidImgFileId')
        }).show();
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            config = component.config;

        if(config) {
            vm.set('codeList', config.codeList);
            vm.set('applyInfo', config.applyInfo);
            vm.set('readOnlyFlag', config.readOnlyFlag);
            vm.set('expItemData', config.expItemData);
            vm.set('expItemData.trnsYy', config.expItemData.trnsDt.substr(0,4));

            var expItemData = config.expItemData;
            if(expItemData) {
                refs.trnsDtm.setValue(DateUtils.parseDate(expItemData.tdt) + ' ' + expItemData.trnsHr.substr(0,2) + ':' + expItemData.trnsHr.substr(2,2) + ':' + expItemData.trnsHr.substr(4,2));
                refs.splyAmt.setValue(FormatUtils.moneyFormat(expItemData.splyAmt)+' 원');
                refs.stxat.setValue(FormatUtils.moneyFormat(expItemData.stxat)+' 원');
                refs.trnsAmt.setValue(FormatUtils.moneyFormat(expItemData.trnsAmt)+' 원');

                // 적요일자 자동기입
                var trnsDt = config.expItemData.trnsDt;
                var aplRscnText = trnsDt.substr(4, 2) + '/' + trnsDt.substr(6, 2);
                refs.common_input_container.getReferences().aplRscn.setValue(aplRscnText);
            }

            me.setExpItemInputData();
        }
    }

});